def populate_auteur_nom(apps, schema_editor):
    """Remplit auteur_nom depuis auteur_employe"""
    Post = apps.get_model('feed', 'Post')
    Comment = apps.get_model('feed', 'Comment')

    # Posts
    for post in Post.objects.all():
        if post.type_post in ['paiement_forfaitaire', 'planning']:
            post.auteur_nom = 'Système'
        elif post.auteur_employe:
            # Priorité au surnom, sinon nom complet
            post.auteur_nom = post.auteur_employe.surnom or post.auteur_employe.nom_employe
        else:
            post.auteur_nom = 'Anonyme'
        post.save(update_fields=['auteur_nom'])

    # Comments
    for comment in Comment.objects.all():
        if comment.auteur_employe:
            # Priorité au surnom, sinon nom complet
            comment.auteur_nom = comment.auteur_employe.surnom or comment.auteur_employe.nom_employe
        else:
            comment.auteur_nom = 'Anonyme'
        comment.save(update_fields=['auteur_nom'])


